CREATE TABLE IF NOT EXISTS "mercy_parkour_codes" (
    "Map_Number" INT GENERATED BY DEFAULT AS IDENTITY,
    "Map" TEXT,
    "Code" TEXT PRIMARY KEY NOT NULL UNIQUE,
    "Checkpoints" INT,
    "Video" TEXT,
    "Notes" TEXT,
    "Author" TEXT,
    "Difficulty" TEXT,
    "Sit" TEXT,
    "Cloud" TEXT,
    "Stuck_Balance" TEXT,
    "Softlock" TEXT,
    "Many_Orbs" TEXT,
	"Difficulty_Integer" INT
);

CREATE TABLE IF NOT EXISTS DailyCode (
  "id" SERIAL PRIMARY KEY,
  "date" DATE UNIQUE NOT NULL,
  "Map_Number" INT REFERENCES mercy_parkour_codes(Map_Number) NOT NULL
);

